import numpy as np


def most_similar_index(documents, query):
    q = np.asarray(query, dtype=float)
    scores = []
    for doc in documents:
        d = np.asarray(doc, dtype=float)
        scores.append(float(np.dot(d, q) / (np.linalg.norm(d) * np.linalg.norm(q))))
    return int(np.argmax(scores))
